menus.statistics='▨  סטטיסטיקה ונתונים';
let reminderIndex=0,reminderPaused=false,reminderTimer;
function reminderItems(){const items=[],end=dayPlus(today(),7);for(const t of S.tasks.filter(t=>t.status!=='הושלם').sort((a,b)=>(a.due||'9999').localeCompare(b.due||'9999'))){if(overdue(t)||t.priority==='דחופה'||t.due&&t.due<=end)items.push({key:t.id,title:(overdue(t)?'משימה באיחור: ':'משימה קרובה: ')+t.title,detail:pname(t.paperId)+' · יעד '+date(t.due),kind:'task',id:t.id,paperId:t.paperId})}for(const p of articleOrder())if(p.due&&p.due<=end&&p.status!=='פורסם')items.push({key:p.id,title:'מועד מאמר: '+p.title,detail:'יעד '+date(p.due),kind:'paper',id:p.id});for(const a of S.activity.filter(a=>importantActivity(a)).slice(0,6))items.push({key:a.id,title:a.message,detail:date(a.date)+' · '+pname(a.paperId),kind:a.paperId?'paper':'activity',id:a.paperId});return items.length?items:[{key:'empty',title:'אין כרגע משימות דחופות או מועדים קרובים',detail:'אפשר לפתוח מאמר ולהגדיר את הצעד הבא.',kind:'none'}]}
function reminderBox(){const a=reminderItems();reminderIndex%=a.length;const item=a[reminderIndex];return '<section class="reminder-box" aria-label="עדכונים ותזכורות"><div class="reminder-heading"><strong>עדכונים ותזכורות</strong><span id="reminder-count">'+(reminderIndex+1)+' / '+a.length+'</span></div><div id="reminder-content" aria-live="'+(reminderPaused?'polite':'off')+'"><b>'+esc(item.title)+'</b><small>'+esc(item.detail)+'</small></div><div class="reminder-controls">'+action('הקודם','stepReminder(-1)')+action(reminderPaused?'המשך החלפה':'עצירת החלפה','toggleReminders()')+action('הבא','stepReminder(1)')+(item.kind!=='none'?action(item.kind==='task'?'פתיחת המשימה':'פתיחת הפרטים','openReminder()','primary'):'')+'</div></section>'}
function redrawReminder(){const box=$('.reminder-box');if(box)box.outerHTML=reminderBox()}
function stepReminder(delta){const a=reminderItems();reminderIndex=(reminderIndex+delta+a.length)%a.length;redrawReminder()}
function toggleReminders(){reminderPaused=!reminderPaused;try{localStorage.setItem('research-reminders-paused',String(reminderPaused))}catch{}redrawReminder()}
try{reminderPaused=localStorage.getItem('research-reminders-paused')==='true'}catch{}
function startReminderTimer(){clearInterval(reminderTimer);if(!$('.reminder-box'))return;reminderTimer=setInterval(()=>{const box=$('.reminder-box');if(!box){clearInterval(reminderTimer);return}if(!reminderPaused&&!document.hidden&&!box.matches(':hover')&&!box.contains(document.activeElement))stepReminder(1)},8000)}
function openReminder(){const x=reminderItems()[reminderIndex%reminderItems().length];if(x.kind==='task'){if(x.paperId)openPaper(x.paperId);else go('tasks');edit('tasks',x.id)}else if(x.kind==='paper')openPaper(x.id);else go('activity')}
function taskControlCounts(){const selected=paperId||articleFilters.tasks,a=S.tasks.filter(t=>(!selected||t.paperId===selected)&&matches(t)),r=window.taskrange||'הכול',end=dayPlus(today(),7);const scoped=a.filter(t=>r==='הכול'||r==='היום'&&t.due===today()||r==='השבוע'&&t.due>=today()&&t.due<=end&&t.status!=='הושלם'||r==='באיחור'&&overdue(t)||r==='ממתין לשותף'&&t.status===r);return {pending:scoped.filter(t=>t.status!=='הושלם').length,high:scoped.filter(t=>t.status!=='הושלם'&&['דחופה','גבוהה'].includes(t.priority)).length,completed:scoped.filter(t=>t.status==='הושלם').length}}
function selectTaskArticle(id){articleFilters.tasks=id;if(paperId){paperId='';view='tasks';render()}else renderBody()}
function allResearchTasks(){window.taskCategory='';window.taskrange='הכול';filter='';q='';renderBody()}
function taskControlRow(){const n=taskControlCounts(),range=window.taskrange||'הכול';return '<div class="task-summary-row" aria-label="שורת בקרת משימות">'+'<select aria-label="משימות לפי מאמר" title="משימות לפי מאמר" onchange="selectTaskArticle(this.value)"><option value="">משימות לפי מאמר</option>'+S.papers.map(p=>'<option value="'+p.id+'" '+((paperId||articleFilters.tasks)===p.id?'selected':'')+'>'+esc(p.code+' — '+p.title)+'</option>').join('')+'</select><select aria-label="למתי" onchange="window.taskrange=this.value;renderBody()">'+[['הכול','למתי'],['היום','היום'],['השבוע','השבוע'],['באיחור','באיחור'],['ממתין לשותף','ממתין לשותף']].map(([v,l])=>'<option value="'+v+'" '+(range===v?'selected':'')+'>'+l+'</option>').join('')+'</select><select aria-label="עדיפויות" onchange="filter=this.value;renderBody()"><option value="">עדיפויות</option>'+priority.map(v=>'<option '+(filter===v?'selected':'')+'>'+v+'</option>').join('')+'</select>'+action('כל המשימות','allResearchTasks()',!window.taskCategory?'selected':'')+[['pending','לטיפול'],['high','חשיבות גבוהה'],['completed','הושלמו']].map(([k,l])=>'<button class="task-mini-filter '+k+' '+(window.taskCategory===k?'selected':'')+'" onclick="filterTaskCategory(\''+k+'\')"><b>'+n[k]+'</b> <span>'+l+'</span></button>').join('')+'</div>'}
fileFilters.type='';
const nextFiles=files;files=function(){const previous=S.files;S.files=previous.filter(f=>!fileFilters.type||fileExtension(f)===fileFilters.type);try{return nextFiles()}finally{S.files=previous}};
function fileExtension(f){return f.name?.includes('.')?f.name.split('.').pop().toLowerCase():'none'}
function fileTypeControl(){return '<label>סוג קובץ<select aria-label="סוג קובץ" onchange="setFileFilter(\'type\',this.value)"><option value="">כל סוגי הקבצים</option>'+[...new Set(S.files.map(fileExtension))].sort().map(ext=>'<option value="'+ext+'" '+(fileFilters.type===ext?'selected':'')+'>'+(ext==='none'?'ללא סיומת':ext.toUpperCase())+'</option>').join('')+'</select></label>'}
schemas.analyses.push(['questionText','שאלת המחקר','text'],['approach','גישת מחקר',['quant','qual','mixed']],['rationale','הסבר ההתאמה','text'],['assumptions','תנאי שימוש','text'],['alternatives','חלופות','text'],['limitations','מגבלות','text']);
const nextRecords=records;records=function(kind){if(kind!=='analyses')return nextRecords(kind);return '<section class="planning-header"><h2>תכנון ניתוחים</h2><p>עוזר לבחירת שיטה ולתכנון בלבד. אין עיבוד נתונים או ניתוח אוטומטי.</p><div class="row">'+action('＋ עוזר לבחירת שיטת ניתוח','openAnalysisWizard()','primary')+action('הצע שאלונים מהמאגר','openQuestionnaireAssistant()')+action('＋ כרטיס ידני',"edit('analyses')")+'</div></section><div class="grid">'+sorted(S.analyses).map(a=>'<article class="panel analysis-card"><span class="tag">'+esc(pname(a.paperId))+'</span><h3>'+esc(a.method||a.title)+'</h3><p><b>שאלת המחקר:</b> '+esc(a.questionText||a.title)+'</p>'+[['התאמה',a.rationale],['תנאי שימוש',a.assumptions],['חלופות',a.alternatives],['מגבלות',a.limitations],['הערות',a.notes]].filter(([,v])=>v).map(([k,v])=>'<details><summary>'+k+'</summary><p class="content">'+esc(v)+'</p></details>').join('')+(a.planningSource?externalLink(a.planningSource,'מקור לתכנון'):'')+'<div class="row">'+action('עריכת הכרטיס',"edit('analyses','"+a.id+"')")+action('פתיחת המאמר',"openPaper('"+a.paperId+"')")+'</div></article>').join('')+'</div>'}
let analysisDraft={},analysisSuggestions=[];
function draftInput(key,label,type='textarea',options){const value=analysisDraft[key]||'';return '<label class="field">'+label+(options?'<select name="'+key+'">'+options.map(([v,l])=>'<option value="'+v+'" '+(value===v?'selected':'')+'>'+l+'</option>').join('')+'</select>':type==='textarea'?'<textarea name="'+key+'" required>'+esc(value)+'</textarea>':'<input name="'+key+'" value="'+esc(value)+'">')+'</label>'}
function openAnalysisWizard(){const pid=paperId||analysisDraft.paperId||'';$('#modal').innerHTML='<h2>עוזר לבחירת שיטת ניתוח</h2><p class="muted">1. הגדירו שאלה ונתונים · 2. בדקו התאמה ותנאים · 3. שמרו בחירה במאמר.</p><form id="analysis-wizard"><label class="field">מאמר<select name="paperId" required><option value="">בחרו מאמר</option>'+S.papers.map(p=>'<option value="'+p.id+'" '+(pid===p.id?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select></label>'+draftInput('question','שאלת המחקר')+draftInput('approach','גישת המחקר','select',[['quant','כמותני'],['qual','איכותני'],['mixed','משולב']])+draftInput('variables','משתנים או נושאים ומשמעותם')+draftInput('dataDescription','הנתונים: אופן איסוף, גודל מדגם משוער, יחידת ניתוח, חסרים ומגבלות')+'<fieldset data-approach="quant"><legend>בחירות למחקר כמותני</legend>'+draftInput('goal','מטרה','select',[['describe','תיאור'],['difference','הבדלים בין קבוצות או מדידות'],['association','קשר'],['predict','מסבירים / חיזוי']])+draftInput('outcome','סולם משתנה התוצאה','select',[['continuous','רציף'],['ordinal','סדור'],['binary','בינארי'],['categorical','קטגוריאלי ללא סדר'],['count','ספירות']])+draftInput('dependence','מבנה המדידות','select',[['independent','יחידות עצמאיות'],['paired','שתי מדידות מזווגות'],['repeated','יותר משתי מדידות חוזרות / אשכולות']])+draftInput('groups','מספר קבוצות עצמאיות','select',[['2','שתיים'],['3','שלוש או יותר']])+'</fieldset><fieldset data-approach="qual"><legend>מטרת הניתוח האיכותני</legend>'+draftInput('qualGoal','מוקד','select',[['themes','דפוסי משמעות'],['framework','השוואת מקרים / מסגרת קיימת'],['narrative','סיפורים ורצף חוויות'],['theory','פיתוח תאוריה תהליכית']])+'</fieldset><fieldset data-approach="mixed"><legend>סדר ואינטגרציה</legend>'+draftInput('mixedGoal','מערך','select',[['converge','שני רכיבים במקביל'],['explain','כמותני ואז איכותני להסבר'],['explore','איכותני ואז כמותני לפיתוח ובחינה']])+'</fieldset><div class="modalfoot">'+action('ביטול',"document.querySelector('#modal').close()")+'<button class="primary">הצגת הצעה מנומקת</button></div></form>';$('#modal').showModal();const f=$('#analysis-wizard');const update=()=>f.querySelectorAll('[data-approach]').forEach(x=>x.hidden=x.dataset.approach!==f.elements.approach.value);f.elements.approach.onchange=update;f.elements.paperId.onchange=()=>{if(!f.elements.question.value.trim())f.elements.question.value=S.papers.find(p=>p.id===f.elements.paperId.value)?.questions||''};if(pid&&!f.elements.question.value)f.elements.question.value=S.papers.find(p=>p.id===pid)?.questions||'';update();f.onsubmit=e=>{e.preventDefault();analysisDraft=Object.fromEntries(new FormData(f));try{analysisSuggestions=ResearchPlanner.recommend(analysisDraft);showAnalysisRecommendations()}catch(e){toast(e.message,true)}}}
function showAnalysisRecommendations(){$('#modal').innerHTML='<h2>הצעות לתכנון הניתוח</h2><p>'+esc(analysisDraft.question)+'</p>'+analysisSuggestions.map((r,i)=>'<section class="panel"><h3>'+esc(r.method)+'</h3>'+[['למה מתאים',r.why],['תנאי שימוש',r.conditions],['חלופות',r.alternatives],['מגבלות',r.limits]].map(([k,v])=>'<h4>'+k+'</h4><p>'+esc(v)+'</p>').join('')+'<p class="verification-label">'+esc(r.warning)+'</p>'+externalLink(r.source,'מקור מתודולוגי')+action('בחירה ושמירה בכרטיס ניתוח',"saveAnalysisChoice("+i+")",'primary')+'</section>').join('')+'<div class="modalfoot">'+action('חזרה לפרטים','openAnalysisWizard()')+action('סגירה',"document.querySelector('#modal').close()")+'</div>'}
async function saveAnalysisChoice(i){const r=analysisSuggestions[i],d=analysisDraft;if(!r)return;const data={id:uid(),paperId:d.paperId,title:d.question,questionText:d.question,approach:d.approach,variables:d.variables,method:r.method,rationale:r.why,assumptions:r.conditions,alternatives:r.alternatives,limitations:r.limits,notes:r.warning+'\n'+r.context,planningSource:r.source,planningInputs:d,updated:now()};try{acceptSavedState(await queuedMutation('/api/save-record',{kind:'analyses',data,baseline:{}}));$('#modal').close();view='analyses';paperId='';render();toast('הבחירה והנימוק נשמרו בכרטיס המשויך למאמר ולשאלה')}catch(e){toast(e.message,true)}}
let questionnaireContext={paperId:'',question:'',selected:[]},questionnaireCandidates=[];
function openQuestionnaireAssistant(pid=paperId){questionnaireContext.paperId=pid||questionnaireContext.paperId;$('#modal').innerHTML='<h2>הצע שאלונים מהמאגר</h2><form id="questionnaire-query"><label class="field">מאמר<select name="paperId" required><option value="">בחרו מאמר</option>'+S.papers.map(p=>'<option value="'+p.id+'" '+(questionnaireContext.paperId===p.id?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select></label><label class="field">שאלת המחקר<textarea name="question" required>'+esc(questionnaireContext.question||S.papers.find(p=>p.id===questionnaireContext.paperId)?.questions||'')+'</textarea></label><p class="muted">התאמה לפי נושאים ומידע שנשמר במאגר בלבד; אין אישור התאמה או תיקוף אוטומטי.</p><div class="modalfoot">'+action('ביטול',"document.querySelector('#modal').close()")+'<button class="primary">הצעת שאלונים והשוואה</button></div></form>';$('#modal').showModal();const f=$('#questionnaire-query');f.elements.paperId.onchange=()=>{f.elements.question.value=S.papers.find(p=>p.id===f.elements.paperId.value)?.questions||''};f.onsubmit=e=>{e.preventDefault();questionnaireContext={...Object.fromEntries(new FormData(f)),selected:[]};questionnaireCandidates=ResearchPlanner.suggest(S.tools,questionnaireContext.question);showQuestionnaireComparison()}}
function validityCaution(t){return !t.validity||/נדרש אימות|לא הוזן|לבדוק|טרם אומת/.test(t.validity)?'חסר מידע מאומת על תיקוף; יש לבדוק במקור ובאוכלוסיית המחקר.':'תיעוד במאגר: '+t.validity+' — אינו מאמת גרסה מתורגמת או התאמה לאוכלוסייה שלך.'}
function showQuestionnaireComparison(){$('#modal').innerHTML='<h2>השוואת שאלונים מהמאגר</h2><p>'+esc(questionnaireContext.question)+'</p>'+(questionnaireCandidates.length?'<div class="questionnaire-comparison">'+questionnaireCandidates.map(({tool:t,broad,matched},i)=>'<article class="panel"><label><input type="checkbox" value="'+t.id+'" '+(questionnaireContext.selected.includes(t.id)?'checked':'')+' onchange="chooseQuestionnaire(this)"> <b>'+esc(t.name)+'</b></label><p><b>מה נמדד:</b> '+esc(t.measures||t.purpose||'חסר מידע במאגר')+'</p><p><b>התאמה לשאלה:</b> '+(broad?'חפיפה כללית בנושא בלבד; לא נמצאה התאמה מספקת למבנה הספציפי.':'בתיאור הכלי ובשאלה מופיעים הממדים '+esc(matched.map(k=>ResearchPlanner.topicLabels[k]).join(', '))+'. בדוק שההגדרה התפעולית בשאלון תואמת לשאלה ולמערך שלך.')+'</p><p>'+esc(t.population||'אוכלוסייה לא תועדה')+' · '+esc(t.language||'שפה לא תועדה')+'</p><p class="verification-label">'+esc(validityCaution(t))+'</p><p>'+esc(t.verificationNotes||'')+'</p>'+externalLink(t.questionnaireUrl,t.questionnaireLinkLabel||'פתיחת השאלון')+(!t.questionnaireUrl?'<p class="verification-label">אין במאגר קישור מאומת לשאלון עצמו; הקישורים הבאים הם למאמר או למקור.</p>':'')+externalLink(t.link,'מקור הכלי / תיקוף — יש לבדוק את תוכנו')+(t.links||[]).map(l=>externalLink(l.url,l.label||'מקור נוסף')).join('')+'<p class="muted">מקור: '+esc(t.source||'מקור תיקוף חסר')+'</p></article>').join('')+'</div>':empty('אין שאלון מתאים במאגר לשאלה שנוסחה. אין להסיק שאין כלי מתאים מחוץ למאגר.'))+'<div class="modalfoot">'+action('חזרה לשאלה','openQuestionnaireAssistant()')+(questionnaireCandidates.length?action('שמירת השאלונים שנבחרו במאמר','saveQuestionnaireChoices()','primary'):'')+action('סגירה',"document.querySelector('#modal').close()")+'</div>'}
function chooseQuestionnaire(input){const set=new Set(questionnaireContext.selected);input.checked?set.add(input.value):set.delete(input.value);questionnaireContext.selected=[...set]}
async function saveQuestionnaireChoices(){if(!questionnaireContext.selected.length){toast('בחרו לפחות שאלון אחד');return}try{acceptSavedState(await workspaceMutation({action:'select-questionnaires',paperId:questionnaireContext.paperId,question:questionnaireContext.question,toolIds:questionnaireContext.selected}));$('#modal').close();openPaper(questionnaireContext.paperId);toast('השאלונים שנבחרו נשמרו במאמר עם שאלת המחקר')}catch(e){toast(e.message,true)}}
const nextPaper=paper;paper=function(){const p=S.papers.find(p=>p.id===paperId);return nextPaper()+(tab==='overview'?'<section class="panel"><div class="sectionhead"><h3>שאלונים שנבחרו למחקר</h3>'+action('הצע שאלונים מהמאגר',"openQuestionnaireAssistant('"+p.id+"')")+'</div>'+(p.questionnaireSelections||[]).map(x=>'<article><h4>'+esc(x.question)+'</h4><ul>'+x.toolIds.map(id=>{const t=S.tools.find(t=>t.id===id);return '<li>'+esc(t?.name||'כלי שאינו זמין במאגר')+(t?.questionnaireUrl?externalLink(t.questionnaireUrl,'פתיחת שאלון'):'')+'<p class="muted">'+esc(x.rationales?.[id]||'יש לבדוק התאמה ותיקוף.')+'</p></li>'}).join('')+'</ul></article>').join('')+'</section>':'')};
const nextRender=render;render=function(){const statistics=view==='statistics';if(statistics)view='analyses';nextRender();if(statistics){view='statistics';document.querySelectorAll('#nav .active').forEach(x=>x.classList.remove('active'));$('#title').textContent='סטטיסטיקה ונתונים';$('#body').innerHTML='<section class="panel"><h2>סטטיסטיקה ונתונים</h2><p>האזור נוסף לסביבת המחקר. התוכן והאפשרויות ייבנו לפי הפירוט שתמסור בהמשך.</p></section>'}if(!$('#nav button[data-statistics]')){const b=document.createElement('button');b.dataset.statistics='true';b.className=statistics?'active':'';b.textContent='▨ סטטיסטיקה ונתונים';b.onclick=()=>go('statistics');$('#nav').append(b)}};
const nextRenderBody=renderBody;renderBody=function(){nextRenderBody();if(view==='tasks'||paperId&&tab==='tasks'){const top=$('.workspace-top');if(top){top.querySelector('.hero-controls')?.insertAdjacentHTML('afterbegin',action('＋ הוסף משימה',"edit('tasks')",'primary task-add'))}else{const head=document.createElement('div');head.className='task-page-heading';head.innerHTML=action('＋ הוסף משימה',"edit('tasks')",'primary task-add');$('#body').prepend(head)}const old=$('.task-unified-toolbar');if(old)old.outerHTML=taskControlRow();else ($('.workspace-top')||$('#body')).insertAdjacentHTML('beforeend',taskControlRow())}if(view==='files'||paperId&&tab==='files'){const row=$('.file-search-row');row?.insertAdjacentHTML('beforeend',fileTypeControl())}if(!paperId&&view==='dashboard'){const top=$('.workspace-top');top?.insertAdjacentHTML('afterbegin',reminderBox())}startReminderTimer()};

// Research data workspace: structural inspection only; no inferential analysis is performed.
let statisticsDraft={paperId:'',approach:'quant',file:null,rows:[],headers:[],quality:null,parseError:''};
function parseResearchCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'){row.push(cell.replace(/\r$/,''));cell='';if(row.some(x=>x.trim()))rows.push(row);row=[]}else cell+=c}if(quoted)throw Error('הקובץ מכיל שדה טקסט שלא נסגר במירכאות.');if(cell.length||row.length){row.push(cell.replace(/\r$/,''));if(row.some(x=>x.trim()))rows.push(row)}if(rows.length<2)throw Error('נדרשת שורת כותרת ולפחות שורת נתונים אחת.');const headers=rows.shift().map((h,i)=>h.trim()||('עמודה '+(i+1)));if(new Set(headers).size!==headers.length)throw Error('נמצאו שמות עמודות כפולים. שנו אותם לפני הטעינה.');const width=headers.length,normalized=rows.map((r,i)=>{if(r.length>width&&r.slice(width).some(x=>x.trim()))throw Error('מספר הערכים בשורה '+(i+2)+' גדול ממספר העמודות. בדקו את מפרידי ה־CSV.');return Array.from({length:width},(_,j)=>r[j]??'')});const blanks=headers.map((_,j)=>normalized.reduce((n,r)=>n+(!r[j].trim()?1:0),0));const signatures=new Set();let duplicateRows=0;for(const r of normalized){const k=JSON.stringify(r);if(signatures.has(k))duplicateRows++;else signatures.add(k)}return {headers,rows:normalized,quality:{rowCount:normalized.length,columnCount:headers.length,blankCells:blanks.reduce((a,b)=>a+b,0),blankByColumn:headers.map((name,i)=>({name,count:blanks[i]})),duplicateRows}}}
function statisticsPage(){const datasets=S.analyses.filter(a=>a.type==='statistics_dataset'||a.type==='statistics_attachment');return '<div class="statistics-workspace"><header class="statistics-heading"><div><h2>סטטיסטיקה ונתונים</h2></div></header><div class="statistics-layout"><section class="panel statistics-import"><div class="sectionhead"><div><h3>קליטת קובץ נתונים</h3><p class="muted">קובץ המקור יישמר כמות שהוא. בדיקת המבנה והניתוח התיאורי מתבצעים בדפדפן.</p></div><span class="statistics-pill">עד 20MB לתצוגה מקדימה</span></div><div class="statistics-form"><label class="field">מאמר<select id="statistics-paper"><option value="">בחרו מאמר</option>'+S.papers.map(p=>'<option value="'+esc(p.id)+'" '+(statisticsDraft.paperId===p.id?'selected':'')+'>'+esc(p.code? p.code+' — '+p.title:p.title)+'</option>').join('')+'</select></label><label class="field">גישת המחקר<select id="statistics-approach">'+[['quant','כמותני'],['qual','איכותני'],['mixed','משולב']].map(([v,l])=>'<option value="'+v+'" '+(statisticsDraft.approach===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label><label class="field statistics-file-field">קובץ נתונים (CSV)<input id="statistics-file" type="file" accept=".csv,text/csv" onchange="previewResearchCsv(this.files?.[0])"><small>נדרש CSV עם כותרות עמודות. הקובץ המקורי אינו משתנה.</small></label><div id="statistics-error" class="statistics-error" '+(statisticsDraft.parseError?'':'hidden')+'>'+esc(statisticsDraft.parseError)+'</div></div>'+(statisticsDraft.quality?statisticsPreview():'<div class="statistics-empty"><span>▤</span><b>בחרו מאמר וקובץ כדי להתחיל</b><small>קובץ CSV יקבל ניתוח תיאורי ראשוני. קובץ מסוג אחר יישמר כחומר עזר ללא ניתוח במסך זה.</small></div>')+'</section><aside class="statistics-side"><section class="panel"><div class="sectionhead"><h3>תכנון שיטה</h3><span class="tag">ללא עיבוד אוטומטי</span></div><p>בחרו את מטרת המחקר והנתונים כדי לקבל הצעת שיטה מנומקת, עם תנאי שימוש, חלופות ומגבלות.</p>'+action('פתיחת עוזר בחירת שיטה','openAnalysisWizard()','primary')+'<p class="muted">הצעה היא לתכנון בלבד; ההכרעה והבדיקה המתודולוגית נשארות אצלך.</p></section><section class="panel"><div class="sectionhead"><h3>שלבי עבודה נוספים</h3></div><div class="planned-item"><b>נתונים איכותניים</b><span>תמלול, קידוד ותיעוד החלטות — בתכנון</span></div><div class="planned-item"><b>מחקר משולב</b><span>חיבור בין ממצאים כמותניים ואיכותניים — בתכנון</span></div><div class="planned-item"><b>ניתוחים סטטיסטיים</b><span>חישובי מדדים והסקה — לא זמינים במסך זה</span></div></section></aside></div><section class="statistics-saved"><div class="sectionhead"><div><h3>קובצי נתונים שנשמרו</h3><p class="muted">הרשומות משויכות למאמר ולמקור הקובץ.</p></div><span class="statistics-count">'+datasets.length+'</span></div>'+(datasets.length?'<div class="statistics-dataset-list">'+datasets.slice().sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).map(d=>'<article class="statistics-dataset"><div><b>'+esc(d.title)+'</b><span>'+esc(pname(d.paperId))+' · '+esc(d.fileName||'קובץ CSV')+'</span></div><div class="statistics-dataset-stats">'+(d.type==='statistics_attachment'?'<span>קובץ עזר · לא נותח אוטומטית</span>':'<span>'+d.rowCount+' שורות</span><span>'+d.columnCount+' עמודות</span><span>'+d.blankCells+' תאים ריקים</span>')+'</div>'+(d.fileId?'<div class="statistics-dataset-actions">'+(d.type==='statistics_dataset'?'<button type="button" onclick="openSavedResearchData(\''+encodeURIComponent(d.fileId)+'\')">הצגת ניתוח תיאורי</button>':'')+'<a href="/api/file/'+encodeURIComponent(d.fileId)+'">הורדת קובץ המקור</a></div>':'')+'</article>').join('')+'</div>':empty('טרם נשמרו קובצי נתונים.'))+'</section></div>'}
function statisticsPreview(){const q=statisticsDraft.quality,headers=statisticsDraft.headers,rows=statisticsDraft.rows;return '<div class="statistics-preview"><div class="statistics-metrics"><div><b>'+q.rowCount+'</b><span>שורות נתונים</span></div><div><b>'+q.columnCount+'</b><span>עמודות</span></div><div><b>'+q.blankCells+'</b><span>תאים ריקים</span></div><div><b>'+q.duplicateRows+'</b><span>שורות זהות</span></div></div><div class="statistics-table-wrap"><table><thead><tr>'+headers.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,6).map(r=>'<tr>'+r.map(v=>'<td>'+esc(v||'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div><details class="statistics-blanks"><summary>חסרים לפי עמודה</summary><div>'+q.blankByColumn.map(x=>'<span>'+esc(x.name)+': '+x.count+'</span>').join('')+'</div></details><p class="statistics-caution">בדיקות מבניות בלבד. שורות זהות או תאים ריקים אינם מעידים כשלעצמם על שגיאה. לא חושבו מובהקות, קשרים או ממצאים.</p><div class="statistics-save-row"><label class="field">תיאור קצר של הקובץ (רשות)<input id="statistics-label" maxlength="120" placeholder="למשל: נתוני שאלון לפני ניקוי"></label><button type="button" class="primary" onclick="saveResearchCsv()" '+(!statisticsDraft.paperId||!statisticsDraft.file?'disabled':'')+'>שמירת הקובץ והבדיקה</button></div></div>'}
function previewResearchCsv(file){statisticsDraft.file=file||null;statisticsDraft.parseError='';statisticsDraft.quality=null;statisticsDraft.rows=[];statisticsDraft.headers=[];statisticsDraft.paperId=$('#statistics-paper')?.value||statisticsDraft.paperId;const err=$('#statistics-error');if(!file){renderBody();return}if(!statisticsDraft.paperId){statisticsDraft.parseError='בחרו תחילה מאמר שאליו ישויך הקובץ.';renderBody();return}if(file.size>20*1024*1024){statisticsDraft.parseError='הקובץ גדול מ־20MB. לתצוגה מקדימה במסך זה בחרו קובץ קטן יותר.';renderBody();return}if(!file.name.toLowerCase().endsWith('.csv')){statisticsDraft.parseError='בשלב זה ניתן לטעון קובצי CSV בלבד.';renderBody();return}const reader=new FileReader();reader.onload=()=>{try{const result=parseResearchCsv(String(reader.result||'').replace(/^\uFEFF/,''));statisticsDraft.headers=result.headers;statisticsDraft.rows=result.rows;statisticsDraft.quality=result.quality;statisticsDraft.parseError=''}catch(e){statisticsDraft.parseError=e.message}renderBody()};reader.onerror=()=>{statisticsDraft.parseError='לא ניתן היה לקרוא את הקובץ בדפדפן.';renderBody()};reader.readAsText(file,'UTF-8')}
async function saveResearchCsv(){const d=statisticsDraft;if(!d.paperId||!d.file||!d.quality){toast('בחרו מאמר וקובץ CSV תקין');return}const p=S.papers.find(x=>x.id===d.paperId);if(!p){toast('המאמר שנבחר אינו קיים עוד. רעננו את המסך.',true);return}const button=$('.statistics-save-row button');if(button)button.disabled=true;try{S=await api('/api/upload',{name:d.file.name,data:await asBase64(d.file),paperId:d.paperId,category:'נתונים וניתוח',sensitive:false});const f=S.files.find(x=>x.name===d.file.name&&x.paperId===d.paperId&&x.category==='נתונים וניתוח'&&x.date);if(!f)throw Error('הקובץ הועלה אך לא נמצאה רשומת הקובץ בחזרה מהשרת.');const label=$('#statistics-label')?.value?.trim(),data={id:uid(),type:'statistics_dataset',paperId:d.paperId,fileId:f.id,fileName:d.file.name,title:label||d.file.name,approach:d.approach,rowCount:d.quality.rowCount,columnCount:d.quality.columnCount,blankCells:d.quality.blankCells,duplicateRows:d.quality.duplicateRows,blankByColumn:d.quality.blankByColumn,inspection:'structural_only',updated:now()};acceptSavedState(await queuedMutation('/api/save-record',{kind:'analyses',data,baseline:{}}));statisticsDraft={paperId:d.paperId,approach:d.approach,file:null,rows:[],headers:[],quality:null,parseError:''};renderBody();toast('הקובץ והבדיקה המבנית נשמרו במאמר '+p.title)}catch(e){toast('השמירה נכשלה: '+e.message,true);if(button)button.disabled=false}}
function renderStatistics(){const was=paperId;paperId='';$('#title').textContent='סטטיסטיקה ונתונים';document.querySelectorAll('#nav .active').forEach(x=>x.classList.remove('active'));document.querySelector('#nav button[data-statistics]')?.classList.add('active');$('#body').innerHTML=statisticsPage();const p=$('#statistics-paper');if(p)p.onchange=()=>{statisticsDraft.paperId=p.value;if(statisticsDraft.file)previewResearchCsv(statisticsDraft.file)};const a=$('#statistics-approach');if(a)a.onchange=()=>statisticsDraft.approach=a.value}
const statisticsAwareRender=render;render=function(){const statistics=view==='statistics';if(statistics)view='analyses';statisticsAwareRender();if(statistics){view='statistics';renderStatistics()}if(!$('#nav button[data-statistics]')){const b=document.createElement('button');b.dataset.statistics='true';b.className=statistics?'active':'';b.innerHTML='<span class="nav-category-icon">▨</span> <span class="nav-category-label">סטטיסטיקה ונתונים</span>';b.onclick=()=>go('statistics');$('#nav').append(b)}};
const regularStatisticsBody=renderBody;renderBody=function(){if(view==='statistics'){renderStatistics();return}regularStatisticsBody()};
// Keep the app's fixed right navigation free from nested <aside> layout rules.
const baseStatisticsPage=statisticsPage;statisticsPage=function(){let html=baseStatisticsPage();html=html.replace('<aside class="statistics-side">','<section class="statistics-side">').replace('</aside></div><section class="statistics-saved">','</section></div><section class="statistics-saved">');html=html.replace(/<section class="panel"><div class="sectionhead"><h3>תכנון שיטה<\/h3>[\s\S]*?<\/section>/,'');const actions='';return html.replace('<div class="statistics-stage-grid">',actions+'<div class="statistics-stage-grid">')};

// Descriptive analysis for questionnaire CSVs; calculations run locally in the signed-in page.
statisticsDraft.analysis=null;statisticsDraft.attachmentOnly=false;statisticsDraft.savedFileId='';
function analyzeResearchRows(headers,rows){const columns=headers.map((name,j)=>{const values=rows.map(r=>String(r[j]??'').trim()),valid=values.filter(Boolean),numeric=valid.map(v=>/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(v)?Number(v):NaN),isNumeric=valid.length>0&&numeric.every(Number.isFinite),counts=new Map();for(const v of valid)counts.set(v,(counts.get(v)||0)+1);const freq=[...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0],'he'));if(isNumeric){const x=numeric.slice().sort((a,b)=>a-b),sum=x.reduce((a,b)=>a+b,0),median=x.length%2?x[(x.length-1)/2]:(x[x.length/2-1]+x[x.length/2])/2,mean=sum/x.length,variance=x.length>1?x.reduce((a,v)=>a+(v-mean)**2,0)/(x.length-1):null,sd=variance===null?null:Math.sqrt(variance),maxFrequency=freq[0]?.[1]||0,mode=maxFrequency>1?freq.filter(([,n])=>n===maxFrequency).map(([v])=>v):[];return {name,type:'numeric',n:x.length,missing:values.length-x.length,unique:counts.size,min:x[0],max:x[x.length-1],range:x[x.length-1]-x[0],mean,median,mode,variance,sd,frequencies:freq.slice(0,6)}}return {name,type:'categorical',n:valid.length,missing:values.length-valid.length,unique:counts.size,mode:freq.length&&freq[0][1]>1?freq.filter(([,n])=>n===freq[0][1]).map(([v])=>v):[],frequencies:freq.slice(0,6)}});const missing=columns.reduce((n,c)=>n+c.missing,0),total=rows.length*headers.length;return {rows:rows.length,columns:headers.length,missing,missingPct:total?missing/total*100:0,duplicateRows:rows.length-new Set(rows.map(r=>JSON.stringify(r))).size,variables:columns}}
function statNum(n){return Number(n).toLocaleString('he-IL',{maximumFractionDigits:2})}
function statisticFrequencyHtml(c){return c.frequencies.map(([v,n])=>'<span>'+esc(v.length>80?v.slice(0,77)+'…':v)+' · '+n+' ('+statNum(n/c.n*100)+'%)</span>').join('')}
function statisticsPreview(){const q=statisticsDraft.quality,headers=statisticsDraft.headers,rows=statisticsDraft.rows,an=statisticsDraft.analysis;return '<div class="statistics-preview"><div class="statistics-metrics"><div><b>'+q.rowCount+'</b><span>תצפיות / שורות</span></div><div><b>'+q.columnCount+'</b><span>משתנים / עמודות</span></div><div><b>'+q.blankCells+'</b><span>ערכים חסרים</span></div><div><b>'+q.duplicateRows+'</b><span>שורות זהות (דגל לבדיקה)</span></div></div><section class="statistics-results"><div class="sectionhead"><div><h3>ניתוח תיאורי ראשוני</h3><p class="muted">נותחו '+an.rows+' שורות ו־'+an.columns+' משתנים מתוך קובץ ה־CSV.</p></div><span class="statistics-pill">חישוב מקומי בדפדפן</span></div><p class="statistics-caution">הוצגו התפלגויות, מספר תשובות תקינות וחסרים. למשתנים מספריים חושבו ממוצע, חציון, טווח וסטיית תקן. קודים מספריים מוצגים כמספרים ללא פירוש של סולם המדידה. לא בוצעו מבחני מובהקות, בדיקות קשר, הסקה, ניקוי נתונים או ניתוח תוכן.</p><div class="statistics-table-wrap statistics-results-table"><table><thead><tr><th>משתנה / שאלה</th><th>סוג שזוהה</th><th>תקין</th><th>חסרים</th><th>ערכים ייחודיים</th><th>סיכום תיאורי / שכיחויות מובילות</th></tr></thead><tbody>'+an.variables.map(c=>'<tr><td>'+esc(c.name)+'</td><td>'+(c.type==='numeric'?'מספרי':'קטגוריאלי / טקסט')+'</td><td>'+c.n+'</td><td>'+c.missing+'</td><td>'+c.unique+'</td><td>'+(c.type==='numeric'?'<b>ממוצע '+statNum(c.mean)+' · חציון '+statNum(c.median)+'</b><br>טווח '+statNum(c.min)+'–'+statNum(c.max)+(c.sd===null?'':' · סטיית תקן '+statNum(c.sd))+'<details class="statistics-frequencies"><summary>התפלגות ערכים</summary><div>'+statisticFrequencyHtml(c)+'</div></details>':'<b>'+statisticsTopCategory(c)+'</b><details class="statistics-frequencies"><summary>התפלגות ערכים</summary><div>'+statisticFrequencyHtml(c)+'</div>'+(c.unique>c.frequencies.length?'<small>מוצגים '+c.frequencies.length+' הערכים השכיחים ביותר מתוך '+c.unique+'.</small>':'')+'</details>')+'</td></tr>').join('')+'</tbody></table></div><p class="muted">שורות זהות אינן נמחקות. שיעור הערכים החסרים בכלל הטבלה: '+statNum(an.missingPct)+'%.</p></section><div class="statistics-table-wrap"><table><thead><tr>'+headers.slice(0,8).map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(0,4).map(r=>r.slice(0,8).map(v=>'<td>'+esc(v||'—')+'</td>').join('')).map(r=>'<tr>'+r+'</tr>').join('')+'</tbody></table></div><details class="statistics-blanks"><summary>חסרים לפי עמודה</summary><div>'+q.blankByColumn.filter(x=>x.count).map(x=>'<span>'+esc(x.name)+': '+x.count+'</span>').join('')+'</div></details><div class="statistics-save-row"><label class="field">תיאור קצר של הקובץ (רשות)<input id="statistics-label" maxlength="120" placeholder="למשל: נתוני שאלון לפני ניקוי"></label><button type="button" class="primary" onclick="saveResearchCsv()" '+(!statisticsDraft.paperId||!statisticsDraft.file?'disabled':'')+'>שמירת הקובץ והבדיקה</button></div></div>'}
previewResearchCsv=function(file){statisticsDraft.file=file||null;statisticsDraft.savedFileId='';statisticsDraft.parseError='';statisticsDraft.quality=null;statisticsDraft.analysis=null;statisticsDraft.attachmentOnly=false;statisticsDraft.rows=[];statisticsDraft.headers=[];statisticsDraft.paperId=$('#statistics-paper')?.value||statisticsDraft.paperId;if(!file){renderBody();return}if(!statisticsDraft.paperId){statisticsDraft.parseError='בחרו תחילה מאמר שאליו ישויך הקובץ.';renderBody();return}if(file.size>50*1024*1024){statisticsDraft.parseError='הקובץ גדול מ־50MB, מגבלת ההעלאה הקיימת באתר.';renderBody();return}const isCsv=/\.csv$/i.test(file.name)||file.type==='text/csv';if(!isCsv){statisticsDraft.attachmentOnly=true;renderBody();return}if(file.size>20*1024*1024){statisticsDraft.parseError='CSV לניתוח מוגבל ל־20MB. ניתן לשמור קובץ גדול יותר כחומר עזר באזור קבצים וגרסאות.';renderBody();return}const reader=new FileReader();reader.onload=()=>{try{const result=parseResearchCsv(String(reader.result||'').replace(/^\uFEFF/,''));statisticsDraft.headers=result.headers;statisticsDraft.rows=result.rows;statisticsDraft.quality=result.quality;statisticsDraft.analysis=analyzeResearchRows(result.headers,result.rows);statisticsDraft.parseError=''}catch(e){statisticsDraft.parseError=e.message}renderBody()};reader.onerror=()=>{statisticsDraft.parseError='לא ניתן היה לקרוא את הקובץ בדפדפן.';renderBody()};reader.readAsText(file,'UTF-8')};
async function saveStatisticsAttachment(){const d=statisticsDraft;if(!d.paperId||!d.file||!d.attachmentOnly){toast('בחרו מאמר וקובץ לצירוף');return}const p=S.papers.find(x=>x.id===d.paperId),button=$('.statistics-attachment-save');if(button)button.disabled=true;try{S=await api('/api/upload',{name:d.file.name,data:await asBase64(d.file),paperId:d.paperId,category:'נתונים וניתוח',sensitive:false});const f=S.files.find(x=>x.name===d.file.name&&x.paperId===d.paperId&&x.category==='נתונים וניתוח');if(!f)throw Error('הקובץ הועלה אך רשומת הקובץ לא חזרה מהשרת.');const data={id:uid(),type:'statistics_attachment',paperId:d.paperId,fileId:f.id,fileName:d.file.name,title:$('#statistics-attachment-label')?.value?.trim()||d.file.name,approach:d.approach,updated:now()};acceptSavedState(await queuedMutation('/api/save-record',{kind:'analyses',data,baseline:{}}));statisticsDraft={paperId:d.paperId,approach:d.approach,file:null,rows:[],headers:[],quality:null,analysis:null,attachmentOnly:false,savedFileId:'',parseError:''};renderBody();toast('קובץ העזר נשמר במאמר '+p.title+'; לא בוצע בו ניתוח אוטומטי')}catch(e){toast('שמירת הקובץ נכשלה: '+e.message,true);if(button)button.disabled=false}}
saveResearchCsv=async function(){const d=statisticsDraft;if(!d.paperId||!d.file||!d.quality||!d.analysis){toast('בחרו מאמר וקובץ CSV תקין');return}const p=S.papers.find(x=>x.id===d.paperId);if(!p){toast('המאמר שנבחר אינו קיים עוד. רעננו את המסך.',true);return}const button=$('.statistics-save-row button');if(button)button.disabled=true;try{S=await api('/api/upload',{name:d.file.name,data:await asBase64(d.file),paperId:d.paperId,category:'נתונים וניתוח',sensitive:false});const f=S.files.find(x=>x.name===d.file.name&&x.paperId===d.paperId&&x.category==='נתונים וניתוח');if(!f)throw Error('הקובץ הועלה אך לא נמצאה רשומת הקובץ בחזרה מהשרת.');const label=$('#statistics-label')?.value?.trim(),data={id:uid(),type:'statistics_dataset',paperId:d.paperId,fileId:f.id,fileName:d.file.name,title:label||d.file.name,approach:d.approach,rowCount:d.quality.rowCount,columnCount:d.quality.columnCount,blankCells:d.quality.blankCells,duplicateRows:d.quality.duplicateRows,blankByColumn:d.quality.blankByColumn,inspection:'descriptive_v1',updated:now()};acceptSavedState(await queuedMutation('/api/save-record',{kind:'analyses',data,baseline:{}}));statisticsDraft={paperId:d.paperId,approach:d.approach,file:null,rows:[],headers:[],quality:null,analysis:null,attachmentOnly:false,savedFileId:'',parseError:''};renderBody();toast('הקובץ והניתוח התיאורי נשמרו במאמר '+p.title)}catch(e){toast('השמירה נכשלה: '+e.message,true);if(button)button.disabled=false}};
async function openSavedResearchData(fileId){const entry=S.analyses.find(x=>x.type==='statistics_dataset'&&x.fileId===decodeURIComponent(fileId));if(!entry){toast('לא נמצאה רשומת הנתונים');return}statisticsDraft={paperId:entry.paperId,approach:entry.approach||'other',file:null,rows:[],headers:[],quality:null,analysis:null,attachmentOnly:false,savedFileId:entry.fileId,parseError:''};renderBody();try{const res=await fetch('/api/file/'+encodeURIComponent(entry.fileId),{credentials:'same-origin',cache:'no-store'});if(!res.ok)throw Error('שרת הקבצים החזיר '+res.status);const text=(await res.text()).replace(/^\uFEFF/,'');const result=parseResearchCsv(text);statisticsDraft.headers=result.headers;statisticsDraft.rows=result.rows;statisticsDraft.quality=result.quality;statisticsDraft.analysis=analyzeResearchRows(result.headers,result.rows);renderBody();document.querySelector('.statistics-results')?.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){statisticsDraft.parseError='לא ניתן לנתח את הקובץ השמור: '+e.message;renderBody()}}
const statsPageWithoutBack=statisticsPage;statisticsPage=function(){let html=statsPageWithoutBack();html=html.replace('<h2>סטטיסטיקה ונתונים</h2>','');html=html.replace(/<header class="statistics-heading">[\s\S]*?<\/header>/,'');html=html.replace(/<div class="statistics-page-actions">[\s\S]*?<\/div>/,'');html=html.replace('קובץ נתונים (CSV)','קובץ נתונים או חומר עזר');html=html.replace('accept=".csv,text/csv"','accept="*/*"');html=html.replace('<small>נדרש CSV עם כותרות עמודות. הקובץ המקורי אינו משתנה.</small>','<small>אפשר לצרף קובץ מכל סוג עד 50MB. ניתוח תיאורי זמין כרגע ל־CSV עם כותרות, עד 20MB.</small>');html=html.replace('קובץ CSV ותצוגה מקדימה','CSV וניתוח תיאורי');html=html.replace('עד 20MB לתצוגה מקדימה','CSV לניתוח עד 20MB · צירוף כל סוג עד 50MB');if(!statisticsDraft.quality&&statisticsDraft.file&&statisticsDraft.attachmentOnly){const box='<div class="statistics-attachment-ready"><b>קובץ עזר מוכן לצירוף</b><span>'+esc(statisticsDraft.file.name)+' · '+statNum(statisticsDraft.file.size/1024)+' KB</span><p>האתר ישמור את הקובץ המקורי וישייך אותו למאמר. פורמט זה אינו מפוענח או מנותח במסך זה.</p><label class="field">תיאור קצר (רשות)<input id="statistics-attachment-label" maxlength="120" placeholder="שם תיאורי לקובץ"></label><button type="button" class="primary statistics-attachment-save" onclick="saveStatisticsAttachment()">שמירת קובץ העזר</button></div>';html=html.replace('</section><section class="statistics-side">',box+'</section><section class="statistics-side">')}if(statisticsDraft.parseError){html=html.replace('<div class="statistics-form">','<div class="statistics-form">')}return html};
const statisticsPageBeforeApproachOption=statisticsPage;statisticsPage=function(){let html=statisticsPageBeforeApproachOption();html=html.replace('</select></label><label class="field statistics-file-field">','<option value="other" '+(statisticsDraft.approach==='other'?'selected':'')+'>אחר / לא יודע</option></select></label><label class="field statistics-file-field">');if(!statisticsDraft.quality&&(statisticsDraft.file||statisticsDraft.parseError))html=html.replace(/<div class="statistics-empty">[\s\S]*?<\/div>/,'');return html};
function statisticsTopCategory(c){if(!c.frequencies.length)return 'אין תשובות תקינות';const [v,n]=c.frequencies[0];return 'השכיח ביותר: '+esc(v.length>80?v.slice(0,77)+'…':v)+' · '+n+' ('+statNum(n/c.n*100)+'%)'}

// A general, opt-in Pearson tool. Numeric columns are never assumed to be interval data.
let statisticsPearsonResult=null;
function pearsonLogGamma(z){const p=[676.5203681218851,-1259.1392167224028,771.3234287776531,-176.6150291621406,12.507343278686905,-0.13857109526572012,9.984369578019572e-6,1.5056327351493116e-7];if(z<0.5)return Math.log(Math.PI)-Math.log(Math.sin(Math.PI*z))-pearsonLogGamma(1-z);z-=1;let x=0.9999999999998099;for(let i=0;i<p.length;i++)x+=p[i]/(z+i+1);const t=z+p.length-0.5;return 0.9189385332046727+(z+0.5)*Math.log(t)-t+Math.log(x)}
function pearsonBetaFraction(a,b,x){const max=200,eps=3e-14,fp=1e-300, qab=a+b,qap=a+1,qam=a-1;let c=1,d=1-qab*x/qap;if(Math.abs(d)<fp)d=fp;d=1/d;let h=d;for(let m=1;m<=max;m++){const m2=2*m;let aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<fp)d=fp;c=1+aa/c;if(Math.abs(c)<fp)c=fp;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<fp)d=fp;c=1+aa/c;if(Math.abs(c)<fp)c=fp;d=1/d;const delta=d*c;h*=delta;if(Math.abs(delta-1)<eps)break}return h}
function pearsonRegularizedBeta(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const bt=Math.exp(pearsonLogGamma(a+b)-pearsonLogGamma(a)-pearsonLogGamma(b)+a*Math.log(x)+b*Math.log1p(-x));return x<(a+1)/(a+b+2)?bt*pearsonBetaFraction(a,b,x)/a:1-bt*pearsonBetaFraction(b,a,1-x)/b}
function pearsonPValue(r,n){if(n<3)return null;if(Math.abs(r)>=1)return 0;const df=n-2,t2=(r*r*df)/(1-r*r),x=df/(df+t2);return pearsonRegularizedBeta(x,df/2,0.5)}
function pearsonConfidenceInterval(r,n){if(n<4)return null;const safe=Math.max(-0.999999999999,Math.min(0.999999999999,r)),z=Math.atanh(safe),se=1/Math.sqrt(n-3);return [Math.tanh(z-1.959963984540054*se),Math.tanh(z+1.959963984540054*se)]}
function runStatisticsPearson(){const vars=statisticsDraft.analysis?.variables||[],xi=Number($('#pearson-x')?.value),yi=Number($('#pearson-y')?.value),xv=vars[xi],yv=vars[yi];if(!xv||!yv||xi===yi){toast('בחרו שני משתנים שונים');return}if(!$('#pearson-confirm-x')?.checked||!$('#pearson-confirm-y')?.checked){toast('סמנו ששני המשתנים הם מדדי רווח/יחס ולא קודים או קטגוריות');return}const pairs=statisticsDraft.rows.map(row=>[row[xi],row[yi]]).filter(([a,b])=>/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(String(a??'').trim())&&/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(String(b??'').trim())).map(([a,b])=>[Number(a),Number(b)]),n=pairs.length;if(n<4){statisticsPearsonResult={error:'נדרשות לפחות ארבע תצפיות שלמות כדי לחשב את המתאם ואת רווח הסמך.'};renderBody();return}const mx=pairs.reduce((s,p)=>s+p[0],0)/n,my=pairs.reduce((s,p)=>s+p[1],0)/n,ssx=pairs.reduce((s,p)=>s+(p[0]-mx)**2,0),ssy=pairs.reduce((s,p)=>s+(p[1]-my)**2,0);if(!ssx||!ssy){statisticsPearsonResult={error:'לא ניתן לחשב מתאם כאשר לאחד המשתנים אין שונות.'};renderBody();return}const r=pairs.reduce((s,p)=>s+(p[0]-mx)*(p[1]-my),0)/Math.sqrt(ssx*ssy),p=pearsonPValue(r,n),ci=pearsonConfidenceInterval(r,n);statisticsPearsonResult={x:xv.name,y:yv.name,n,r,p,ci};renderBody()}
function statisticsPearsonPanel(){
 const vars=(statisticsDraft.analysis?.variables||[]).map((v,i)=>({v,i})).filter(x=>x.v.type==='numeric');
 if(vars.length<2)return '<section class="statistics-results statistics-correlation"><h3>בדיקת קשר בין משתנים — פירסון</h3><p>כלי כללי זמין לנתונים מספריים. בקובץ שמוצג כרגע לא זוהו שני משתנים מספריים נקיים: תשובות השאלון נשמרו כתוויות טקסט (למשל „5 = מסכים/ה מאוד”). הן לא יקודדו אוטומטית ולא ייחשבו רציפות בלי החלטת מדידה.</p><p class="statistics-caution">מיפוי סולם, פריטים הפוכים, בניית ציוני ממדים והגדרת השערה עדיין דורשים אישור חוקר. אין כאן תוצאה של מתאם.</p></section>';
 const opts=vars.map(x=>'<option value="'+x.i+'">'+esc(x.v.name)+'</option>').join('');
 let result='';
 if(statisticsPearsonResult){
  if(statisticsPearsonResult.error)result='<p class="statistics-error">'+esc(statisticsPearsonResult.error)+'</p>';
  else result='<div class="statistics-correlation-output"><b>חישוב שבוצע · '+statisticsPearsonResult.n+' זוגות שלמים</b><p>r = '+statNum(statisticsPearsonResult.r)+' · p '+(statisticsPearsonResult.p<0.001?'< .001':'= '+statNum(statisticsPearsonResult.p))+' · רווח סמך 95% ['+statNum(statisticsPearsonResult.ci[0])+', '+statNum(statisticsPearsonResult.ci[1])+']</p><small>המתאם מתאר קשר לינארי במדגם ואינו מוכיח סיבתיות.</small></div>';
 }
 return '<section class="statistics-results statistics-correlation"><div class="sectionhead"><div><h3>בדיקת קשר בין שני משתנים מספריים</h3><p class="muted">מתאם פירסון r · בחירה מפורשת של משתנים ומדידת רווח/יחס</p></div><span class="statistics-pill">חישוב אמיתי בדפדפן</span></div><div class="statistics-correlation-controls"><label class="field">משתנה ראשון<select id="pearson-x">'+opts+'</select></label><label class="field">משתנה שני<select id="pearson-y">'+opts+'</select></label><label><input id="pearson-confirm-x" type="checkbox"> המשתנה הראשון נמדד בסולם רווח/יחס</label><label><input id="pearson-confirm-y" type="checkbox"> המשתנה השני נמדד בסולם רווח/יחס</label></div><p class="statistics-caution">לפני פרשנות יש לבדוק עצמאות תצפיות, לינאריות, חריגים והנחות להסקה. הבדיקה אינה מאמתת אותן אוטומטית; אל תשתמשו בקוד מספרי או בפריט סדרי בלי הצדקה מתודולוגית.</p><button type="button" onclick="runStatisticsPearson()">חישוב Pearson</button>'+result+'</section>';
}
const statisticsPreviewBeforePearson=statisticsPreview;statisticsPreview=function(){let html=statisticsPreviewBeforePearson();return html.replace('</section><div class="statistics-table-wrap">','</section>'+statisticsPearsonPanel()+'<div class="statistics-table-wrap">')};

// Statistics workspace refinements: compact intake, central analyses, and reversible archive.
let showArchivedStatisticsDatasets=false;
async function archiveStatisticsDataset(id,restore=false){const d=S.analyses.find(a=>a.id===id&&['statistics_dataset','statistics_attachment'].includes(a.type));if(!d)return;try{acceptSavedState(await queuedMutation('/api/save-record',{kind:'analyses',data:{...d,archivedAt:restore?'':now()},baseline:{...d}}));renderBody();toast(restore?'הקובץ הוחזר מהרשימה הארכיונית':'קובץ הנתונים הועבר לארכיון')}catch(e){toast(e.message,true)}}
async function deleteStatisticsDataset(id){const d=S.analyses.find(a=>a.id===id&&['statistics_dataset','statistics_attachment'].includes(a.type));if(!d)return;if(!confirm('להעביר את רשומת הנתונים ואת קובץ המקור לסל המחזור? ניתן לשחזר את הקובץ דרך קבצים וגרסאות.'))return;try{acceptSavedState(await queuedMutation('/api/workspace',{action:'delete-statistics-dataset',datasetId:id}));renderBody();toast('רשומת הנתונים הוסרה והקובץ הועבר לסל המחזור')}catch(e){toast(e.message,true)}}
function statisticsSavedSection(){const all=S.analyses.filter(a=>['statistics_dataset','statistics_attachment'].includes(a.type)),active=all.filter(a=>!a.archivedAt),archived=all.filter(a=>a.archivedAt),shown=showArchivedStatisticsDatasets?archived:active;return '<section class="statistics-saved"><div class="sectionhead"><div><h3>קובצי נתונים שנשמרו</h3><p class="muted">הרשומות משויכות למאמר ולמקור הקובץ.</p></div><div class="statistics-saved-tools"><span class="statistics-count">'+(showArchivedStatisticsDatasets?archived.length:active.length)+'</span><button type="button" onclick="showArchivedStatisticsDatasets=!showArchivedStatisticsDatasets;renderBody()">'+(showArchivedStatisticsDatasets?'הצגת קבצים פעילים ('+active.length+')':'הצגת ארכיון ('+archived.length+')')+'</button></div></div>'+(shown.length?'<div class="statistics-dataset-list">'+shown.slice().sort((a,b)=>(b.updated||'').localeCompare(a.updated||'')).map(d=>'<article class="statistics-dataset '+(d.archivedAt?'is-archived':'')+'"><div><b>'+esc(d.title||d.fileName)+'</b><span>'+esc(pname(d.paperId))+' · '+esc(d.fileName||'קובץ CSV')+(d.archivedAt?' · בארכיון':'')+'</span></div><div class="statistics-dataset-stats">'+(d.type==='statistics_attachment'?'<span>קובץ עזר · לא נותח אוטומטית</span>':'<span>'+d.rowCount+' שורות</span><span>'+d.columnCount+' עמודות</span><span>'+d.blankCells+' תאים ריקים</span>')+'</div><div class="statistics-dataset-actions">'+(d.fileId?'<a href="/api/file/'+encodeURIComponent(d.fileId)+'">הורדת קובץ המקור</a>':'')+(d.archivedAt?'<button type="button" onclick="archiveStatisticsDataset(\''+d.id+'\',true)">החזרה לרשימה</button>':'<button type="button" onclick="archiveStatisticsDataset(\''+d.id+'\')">העברה לארכיון</button>')+'<button type="button" class="statistics-delete" onclick="deleteStatisticsDataset(\''+d.id+'\')">מחיקה</button></div></article>').join('')+'</div>':empty(showArchivedStatisticsDatasets?'הארכיון ריק.':'טרם נשמרו קובצי נתונים.'))+'</section>'}
const statisticsPageBeforeLayout=statisticsPage;
statisticsPage=function(){let html=statisticsPageBeforeLayout();html=html.replace(/<div class="statistics-private-note">[\s\S]*?<\/div>/,'');html=html.replace(/<div class="statistics-empty"><span>[\s\S]*?<\/div>/,'');html=html.replace('</section><section class="statistics-side">','</section><section class="statistics-analysis-main"><div class="statistics-analysis-heading"><span class="statistics-eyebrow">סביבת עבודה</span><h3>ניתוחים סטטיסטיים למחקר</h3><p>מתחילים מתיאור הנתונים, וממשיכים למבחן שנבחר במפורש ובהתאם למיפוי המשתנים.</p></div><div class="statistics-analysis-index"><span>תיאור ושכיחויות</span><span>Pearson</span><span>Spearman</span><span>Welch t</span><span>Mann–Whitney U</span></div><div id="statistics-analysis-content"><div class="statistics-analysis-placeholder"><b>בחרו מאמר וקובץ נתונים כדי להתחיל</b><span>הניתוחים והבדיקות יוצגו כאן לאחר קליטת CSV.</span></div></div></section><section class="statistics-side">');const ss=html.indexOf('<section class="statistics-saved">');if(ss>=0){const marker='</section></div>',se=html.indexOf(marker,ss);if(se>=0)html=html.slice(0,ss)+statisticsSavedSection()+html.slice(se+'</section>'.length)}return html};
