renderStatistics=function(){statisticsRenderBeforeCompact();const quickButton=document.querySelector('main > header > button.primary');document.querySelector('#statistics-top-assistant')?.remove();if(quickButton){const b=document.createElement('button');b.id='statistics-top-assistant';b.type='button';b.className='primary statistics-top-assistant';b.textContent='פתיחת עוזר בבחירת שיטה';b.onclick=()=>openAnalysisWizard();quickButton.insertAdjacentElement('afterend',b)}const center=document.querySelector('#statistics-analysis-content'),preview=document.querySelector('.statistics-preview');if(center){if(preview){const pieces=[preview.querySelector('.statistics-metrics'),preview.querySelector('.statistics-results:not(.statistics-guided)'),preview.querySelector('.statistics-mapping-panel'),preview.querySelector('#statistics-guided-slot')].filter(Boolean);if(pieces.length){center.innerHTML='';for(const el of pieces)center.append(el)}else center.innerHTML='<div class="statistics-analysis-placeholder"><b>בחרו מאמר וקובץ נתונים כדי להתחיל</b><span>הניתוחים והבדיקות יוצגו כאן לאחר קליטת CSV.</span></div>'}}};
