render=function(){if(view!=='statistics')document.querySelector('#statistics-top-assistant')?.remove();statisticsRenderRestoreAssistant()};

function statisticsMethodGuideHtml(){const methods=[
 ['סטטיסטיקה תיאורית','לסיכום משתנה יחיד','שמי: שכיחויות ואחוזים. סדרי: חציון וטווח בין־רבעוני לאחר קידוד תקף. רווח/מנה: ממוצע וסטיית תקן כשההתפלגות סבירה; בחציון וטווח בין־רבעוני כשיש הטיה או חריגים.','המדדים התיאוריים מוצגים אחרי טעינת CSV; מיפוי הסולם נשאר באחריות החוקר.','זמין'],
 ['מבחן t של Welch','להשוואת ממוצע בין שתי קבוצות בלתי תלויות','מתאים לתוצאה בסולם רווח/מנה. מדווחים הפרש ממוצעים, רווח סמך, p וגודל אפקט. יש לבדוק עצמאות, התפלגות וחריגים; אין צורך להניח שוויון שונויות.','זמין לחישוב לאחר בחירת משתנים וקבוצות ואישור תנאי השיטה.','זמין'],
 ['Mann–Whitney U','להשוואת שתי קבוצות בלתי תלויות כשנתוני התוצאה סדריים או כשהשוואת דירוגים מתאימה','המבחן משווה דירוגים ואינו מבחן לחציונים בלבד. מוצגים U, AUC ו־Cliff’s δ; ערך p מקורב מוצג רק כשיש לפחות 10 תצפיות שלמות בכל קבוצה.','זמין לחישוב; רווח סמך לאפקט אינו מחושב כרגע.','זמין'],
 ['Pearson r','לקשר לינארי בין שני משתנים בסולם רווח/מנה','יש לבדוק לינאריות, חריגים ועצמאות. מתאם אינו מוכיח סיבתיות.','זמין לחישוב לאחר מיפוי סולמות ובחירת משתנים.','זמין'],
 ['Spearman ρ','לקשר מונוטוני, ובכלל זה משתנים סדריים שקודדו במפורש','בודק קשר על בסיס דירוגים. ערך p מקורב בגרסה זו ורווח סמך אינו מחושב.','זמין לחישוב לאחר קידוד ומיפוי מפורשים.','זמין'],
 ['t מזווג / Wilcoxon signed-rank','להשוואת שתי מדידות של אותם משתתפים','מתאים לפני–אחרי או לזוגות מותאמים. הבחירה תלויה בסולם ובמבנה ההפרשים; לא להשתמש במבחן לקבוצות בלתי תלויות.','עדיין לא זמין לחישוב באפליקציה.','בתכנון'],
 ['ANOVA חד־כיוונית','להשוואת שלוש קבוצות ומעלה','המימוש מחשב ANOVA רגילה, F ו־η². נדרשות תצפיות עצמאיות, בדיקת נורמליות ושוויון שונויות. אין בדיקות המשך; השוואה כוללת אינה אומרת אילו זוגות קבוצות שונים.','זמין לחישוב לאחר בחירה מפורשת של משתנה תוצאה ומשתנה קבוצה. Welch ANOVA ו־Kruskal–Wallis עדיין לא זמינים.','זמין'],
 ['חי־בריבוע / Fisher exact','לקשר בין שני משתנים קטגוריאליים','בודקים טבלת שכיחויות ותדירויות צפויות. Fisher מתאים במיוחד לטבלאות קטנות או לתאים צפויים דלים.','עדיין לא זמין לחישוב באפליקציה.','בתכנון'],
 ['רגרסיה','להערכת קשר מותנה או לניבוי לפי משתנה תוצאה מוגדר','רגרסיה לינארית מתאימה לתוצאה רציפה; לוגיסטית לתוצאה בינארית. צריך להגדיר מנבאים, משתני בקרה, הנחות ותכנית לטיפול בחסרים.','עדיין לא זמין לחישוב באפליקציה.','בתכנון'],
 ['מהימנות ומבנה סולם','לבדיקת פריטים שמיועדים למדוד מושג משותף','אלפא או אומגה אינם מוכיחים חד־ממדיות או תוקף. ניתוח גורמים דורש הצדקה תאורטית, מדגם מתאים ובחירת EFA או CFA מראש.','עדיין לא זמין לחישוב באפליקציה.','בתכנון']
 ];return '<section class="statistics-method-guide"><div class="sectionhead"><div><span class="statistics-eyebrow">מדריך לבחירת ניתוח</span><h3>אילו מדדים ומבחנים מתאימים למחקר?</h3><p class="muted">הבחירה מתחילה בשאלת המחקר, בסולם המדידה ובשאלה אם המדידות בלתי תלויות או מזווגות.</p></div><span class="statistics-pill">'+methods.filter(x=>x[4]==='זמין').length+' שיטות זמינות לחישוב</span></div><div class="statistics-method-grid">'+methods.map(([name,when,why,report,status])=>'<details class="statistics-method-card '+(status==='זמין'?'available':'planned')+'"><summary><b>'+name+'</b><span>'+status+'</span></summary><div><b>מתי כדאי?</b><p>'+when+'</p><b>איך לבחור ומה לדווח</b><p>'+why+'</p><p class="statistics-method-report">'+report+'</p></div></details>').join('')+'</div><p class="statistics-method-note">הסבר כללי לבחירת שיטה, לא המלצה אוטומטית. אין לפרש קשר כסיבתיות; יש לבדוק הנחות, תכנון מדגם וקידוד עם החוקר/ת לפני דיווח.</p></section>'}
const statisticsPageBeforeMethodGuide=statisticsPage;
statisticsPage=function(){let html=statisticsPageBeforeMethodGuide();html=html.replace('<div id="statistics-analysis-content">',statisticsMethodGuideHtml()+'<div id="statistics-analysis-content">');return html};
const renderStatisticsBeforeMethodGuide=renderStatistics;
renderStatistics=function(){renderStatisticsBeforeMethodGuide();document.querySelector('.statistics-side')?.remove()};
